using System;
using System.Buffers.Binary;
using System.Collections.Generic;
using System.Collections.ObjectModel;
using System.Linq;
using System.Text;

namespace SlopArena.Shared
{
    /// <summary>
    /// Pre-baked bone positions for one animation.
    /// Loaded from a .bin file generated by the BakeSkeleton tool.
    /// </summary>
    public sealed class BakedAnimationData
    {
        /// <summary>
        /// Synthetic point holding where the animation draws the hips, relative to the
        /// capsule centre in the fighter's facing frame. Every other point is
        /// hips-relative; bakes without this point use the fixed HipHeight pivot.
        /// </summary>
        public const string HipsOffsetPointName = "_hips_offset";

        private IReadOnlyList<string> _boneNames = Array.Empty<string>();
        private string[] _boneData = Array.Empty<string>();
        private BakedAnim[] _animationData = Array.Empty<BakedAnim>();
        private IReadOnlyList<BakedAnim> _animations = Array.Empty<BakedAnim>();
        private int _hipsOffsetIndex = -1;

        public IReadOnlyList<string> BoneNames
        {
            get => _boneNames;
            init
            {
                _boneData = value.ToArray();
                _boneNames = Array.AsReadOnly(_boneData);
                _hipsOffsetIndex = FindBoneIndex(HipsOffsetPointName);
            }
        }

        public IReadOnlyList<BakedAnim> Animations
        {
            get => _animations;
            init
            {
                _animationData = value.ToArray();
                _animations = Array.AsReadOnly(_animationData);
            }
        }

        /// <summary>Index of <see cref="HipsOffsetPointName"/>, or -1 for legacy bakes.</summary>
        public int HipsOffsetIndex => _hipsOffsetIndex;

        /// <summary>
        /// One baked animation.
        /// </summary>
        public sealed class BakedAnim
        {
            private IReadOnlyList<IReadOnlyList<float>> _frames = Array.Empty<IReadOnlyList<float>>();
            private float[][] _frameData = Array.Empty<float[]>();
            public string Name { get; init; } = "";
            public int FrameCount => _frameData.Length;
            /// <summary>Frames[frame][boneIndex * 3 + component] = x/y/z.</summary>
            public IReadOnlyList<IReadOnlyList<float>> Frames
            {
                get => _frames;
                init
                {
                    _frameData = value.Select(frame => frame.ToArray()).ToArray();
                    _frames = new ReadOnlyCollection<IReadOnlyList<float>>(_frameData
                        .Select(frame => (IReadOnlyList<float>)Array.AsReadOnly(frame)).ToArray());
                }
            }

            public ReadOnlySpan<float> Frame(int index) => _frameData[index];
            internal BakedAnim WithName(string name) => new() { Name = name, _frameData = _frameData, _frames = _frames };
        }

        /// <summary>
        /// Load baked data from .bin format.
        /// </summary>
        public static BakedAnimationData LoadFromBin(byte[] data)
        {
            int pos = 0;

            // Magic
            uint magic = BinaryPrimitives.ReadUInt32LittleEndian(data.AsSpan(pos)); pos += 4;
            if (magic != 0x4C454B53) // "SKEL"
                throw new Exception("Not a valid baked skeleton file");

            uint version = BinaryPrimitives.ReadUInt32LittleEndian(data.AsSpan(pos)); pos += 4;
            if (version != 1)
                throw new Exception($"Unknown version: {version}");

            uint boneCount = BinaryPrimitives.ReadUInt32LittleEndian(data.AsSpan(pos)); pos += 4;
            uint animCount = BinaryPrimitives.ReadUInt32LittleEndian(data.AsSpan(pos)); pos += 4;

            // Bone names
            var boneNames = new string[boneCount];
            for (int i = 0; i < boneCount; i++)
            {
                uint nameLen = BinaryPrimitives.ReadUInt32LittleEndian(data.AsSpan(pos)); pos += 4;
                boneNames[i] = Encoding.UTF8.GetString(data, pos, (int)nameLen);
                pos += (int)nameLen;
            }

            // Animations
            var anims = new BakedAnim[animCount];
            for (int a = 0; a < animCount; a++)
            {
                uint nameLen = BinaryPrimitives.ReadUInt32LittleEndian(data.AsSpan(pos)); pos += 4;
                string animName = Encoding.UTF8.GetString(data, pos, (int)nameLen);
                pos += (int)nameLen;

                uint frameCount32 = BinaryPrimitives.ReadUInt32LittleEndian(data.AsSpan(pos)); pos += 4;
                int frameCount = (int)frameCount32;

                int stride = (int)boneCount * 3;
                var frames = new float[frameCount][];
                for (int f = 0; f < frameCount; f++)
                {
                    var frame = new float[stride];
                    for (int s = 0; s < stride; s++)
                    {
                        frame[s] = BitConverter.Int32BitsToSingle(BinaryPrimitives.ReadInt32LittleEndian(data.AsSpan(pos)));
                        pos += 4;
                    }
                    frames[f] = frame;
                }

                anims[a] = new BakedAnim
                {
                    Name = animName,
                    Frames = frames,
                };
            }

            return new BakedAnimationData
            {
                BoneNames = boneNames,
                Animations = anims,
            };
        }

        /// <summary>
        /// Get the local-space position of a bone at a specific animation frame.
        /// <paramref name="boneIndex"/> indexes <see cref="BoneNames"/> (bake order);
        /// resolve it with <see cref="FindBoneIndex"/>.
        /// Returns true if found. Positions are (x, y, z).
        /// </summary>
        public bool GetBonePosition(string animName, int frameIndex, int boneIndex, out float x, out float y, out float z)
        {
            x = y = z = 0;

            // Find animation
            for (int a = 0; a < _animationData.Length; a++)
            {
                if (_animationData[a].Name == animName)
                {
                    var animation = _animationData[a];
                    int fc = animation.FrameCount;
                    if (frameIndex < 0) frameIndex = 0;
                    if (frameIndex >= fc) frameIndex = fc - 1;

                    if (fc <= 0 || boneIndex < 0) return false;
                    int stride = _boneData.Length * 3;
                    int baseIdx = boneIndex * 3;
                    if (baseIdx + 2 < stride)
                    {
                        var frame = animation.Frame(frameIndex);
                        x = frame[baseIdx];
                        y = frame[baseIdx + 1];
                        z = frame[baseIdx + 2];
                        return true;
                    }
                    return false;
                }
            }
            return false;
        }

        /// <summary>
        /// Read one baked point by animation index; the frame is clamped to the clip.
        /// Returns false when the animation or point index is out of range.
        /// </summary>
        public bool TryGetPoint(int animIndex, int frameIndex, int pointIndex, out float x, out float y, out float z)
        {
            x = y = z = 0;
            if (animIndex < 0 || animIndex >= _animationData.Length || pointIndex < 0 || pointIndex >= _boneData.Length)
                return false;
            var anim = _animationData[animIndex];
            if (anim.FrameCount <= 0) return false;
            if (frameIndex < 0) frameIndex = 0;
            if (frameIndex >= anim.FrameCount) frameIndex = anim.FrameCount - 1;
            int baseIdx = pointIndex * 3;
            var frame = anim.Frame(frameIndex);
            x = frame[baseIdx];
            y = frame[baseIdx + 1];
            z = frame[baseIdx + 2];
            return true;
        }

        /// <summary>
        /// Returns the minimum Y across all bones at frame 0 of the "idle" animation.
        /// Negative = feet/toes below Hips. Used to compute HipHeight for character defs.
        /// Returns 0 if idle animation is not found.
        /// </summary>
        public float GetMinBoneY()
        {
            for (int a = 0; a < _animationData.Length; a++)
            {
                if (_animationData[a].Name == "idle" && _animationData[a].FrameCount > 0)
                {
                    var frame = _animationData[a].Frame(0);
                    float minY = float.MaxValue;
                    for (int b = 0; b < _boneData.Length; b++)
                    {
                        float y = frame[b * 3 + 1];
                        if (y < minY) minY = y;
                    }
                    return minY;
                }
            }
            return 0f;
        }

        /// <summary>
        /// Find animation index by name, or -1.
        /// </summary>
        public int FindAnimIndex(string name)
        {
            for (int i = 0; i < _animationData.Length; i++)
                if (_animationData[i].Name == name)
                    return i;
            return -1;
        }

        /// <summary>
        /// Find bone index by name, or -1. Bones keep bake order, which is independent
        /// of hurtbox definition order, so callers resolve bones by name.
        /// </summary>
        public int FindBoneIndex(string name)
        {
            for (int i = 0; i < _boneData.Length; i++)
                if (_boneData[i] == name)
                    return i;
            return -1;
        }

        /// <summary>
        /// Frame count for an animation, or -1 when the animation is not in the bake.
        /// </summary>
        public int FrameCountFor(string animName)
        {
            int idx = FindAnimIndex(animName);
            return idx >= 0 ? _animationData[idx].FrameCount : -1;
        }
    }
}
